language arduino
#include <AccelStepper.h>

// Define pins
const int stepPin = 3;
const int dirPin = 2;

// Define stepper object
AccelStepper stepper(AccelStepper::DRIVER, stepPin, dirPin);

// Motor configuration
const long stepsPerTurn = 200L; // 1.8 degree motor
const long microsteps = 8;      // 1/8 microstepping
const long totalSteps = 800;    // Steps to move forward and back

void setup() {
  // Initialize the stepper
  stepper.setMaxSpeed(2000);    // Max speed: 2000 steps per second
  stepper.setAcceleration(1000); // Acceleration: 1000 steps per second per second

  // Move to the target position
  stepper.moveTo(totalSteps);
}

void loop() {
  // Run the stepper
  stepper.run();

  // Check if we've reached the target
  if (stepper.distanceToGo() == 0) {
    // Reverse direction and move back
    stepper.setDirection(stepper.currentDirection() == 1 ? -1 : 1);
    stepper.moveTo(-totalSteps);
  }
}
END

