MAKE CODE: P1AM-100: Motor Start/Stop with Seal-In
language arduino
// P1AM-100: Motor start/stop with a seal-in on Productivity1000 I/O modules.
// Slot 1: a discrete input module (or the P1-08SIM switch simulator)
//   ch 1 Start (NO), ch 2 Stop (NC), ch 3 Overload (NC)
// Slot 2: a discrete output module (P1-08TRS relays, P1-08TD1 ...)
//   ch 1 motor contactor, ch 2 run light
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
bool running = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ;   // wait for the modules to sign on
  }
}

void loop() {
  bool start = P1.readDiscrete(inSlot, 1);
  bool stopOk = P1.readDiscrete(inSlot, 2);       // NC: on while not pressed
  running = (start || running) && stopOk;
  P1.writeDiscrete(running, outSlot, 1);
  P1.writeDiscrete(running, outSlot, 2);
}
END

