// Calculate current from voltage and resistance using Ohm's Law: I = V / R
function calculateCurrent(voltage, resistance) {
  if (voltage === undefined || resistance === undefined || resistance === 0) {
    throw new Error("Voltage and resistance must be provided, and resistance cannot be zero.");
  }
  const current = voltage / resistance;
  return current;
}

// Test case: 12 V across 4 ohms
const result = calculateCurrent(12, 4);
console.log(`Current for 12 V across 4 ohms is ${result} A`);
END

